function purchasePageHtml(){var x=ym(),rows=monthPurchases(x.y,x.m),total=rows.reduce(function(s,p){return s+rowAmount(p)},0);return '<section class="page ar3980-page ar430-page"><div class="back-row"><button class="btn ghost" data-action="tab" data-tab="financeHub">برگشت</button><button class="btn gold" data-ar3980="editMonthPurchase">ویرایش / افزودن ردیف</button></div><div class="ar430-hero"><h2>خرید کارگاه — فاکتور واحد ماهانه</h2><p>این فاکتور مستقیماً از خریدهای واقعی همان ماه ساخته می‌شود؛ برای نمایش ماه‌های قبل هیچ خرید مصنوعی یا سند کپی ایجاد نمی‌شود.</p></div>'+purchasePeriodHtml(x)+'<div class="ar430-invoice"><div class="ar430-invoice-head"><div><h3>فاکتور خرید '+MONTHS[x.m-1]+' '+fa(x.y)+'</h3><small>'+fa(rows.length)+' ردیف واقعی</small></div><strong>'+mon(total)+'</strong></div><div class="ar430-columns"><span>ردیف</span><span>شرح</span><span>تعداد</span><span>قیمت واحد / تغییر</span><span>جمع</span></div><div class="ar430-body">'+(rows.map(purchaseRowHtml).join('')||'<div class="ar430-empty">برای این ماه خریدی ثبت نشده است.</div>')+'</div><div class="ar430-grand"><span>جمع کل '+MONTHS[x.m-1]+'</span><b>'+mon(total)+'</b></div></div></section>'}
function blankPurchaseRow(y,m){var t=today(),day=(n(y)===n(t.jy)&&n(m)===n(t.jm))?n(t.jd):1;return {id:'',title:'',quantity:'1',unit:'عدد',unitPrice:'',date:dateText(y,m,day),createdAt:'',readOnly:false}}
