function purchaseDraft(){if(state.ar3980PurchaseDraft)return state.ar3980PurchaseDraft;var x=ym(),rows=monthPurchases(x.y,x.m);state.ar3980PurchaseDraft={year:x.y,month:x.m,sourceIds:rows.map(function(p){return String(p.id||'')}),sourceFingerprint:purchaseFingerprint(x.y,x.m),rows:rows.map(function(p){return {id:String(p.id||''),title:String(p.title||''),quantity:String(purchaseNumber(p.quantity)||1),unit:String(p.unit||'عدد'),unitPrice:String(purchaseUnitPrice(p)||''),date:purchaseDate(p),createdAt:String(p.createdAt||''),readOnly:false}})};if(!state.ar3980PurchaseDraft.rows.length)state.ar3980PurchaseDraft.rows=[blankPurchaseRow(x.y,x.m)];return state.ar3980PurchaseDraft}
function syncPurchaseDraft(){if(!state||state.modal!=='ar3980MonthlyPurchase')return;var d=state.ar3980PurchaseDraft||purchaseDraft(),rows=[];document.querySelectorAll('[data-ar3980-purchase-row]').forEach(function(el){var old=d.rows[n(el.getAttribute('data-index'))]||blankPurchaseRow(d.year,d.month),val=function(role,fallback){var x=el.querySelector('[data-role="'+role+'"]');return x?x.value:fallback};rows.push({id:old.id||'',title:val('title',old.title),quantity:val('quantity',old.quantity),unit:val('unit',old.unit),unitPrice:val('unitPrice',old.unitPrice),date:val('date',old.date),createdAt:old.createdAt||'',readOnly:false})});if(rows.length)d.rows=rows;state.ar3980PurchaseDraft=d}
function purchaseModalHtml(){var d=purchaseDraft();return '<div class="modal-back"><div class="modal ar430-editor"><div class="ar430-editor-head"><h3>خریدهای '+MONTHS[d.month-1]+' '+fa(d.year)+'</h3><p>هر ردیف یک خرید واقعی است. تاریخ و شناسه خریدهای قبلی فقط در صورت ویرایش همان ردیف تغییر می‌کنند.</p></div><div class="ar430-edit-list">'+d.rows.map(function(r,i){return '<div class="ar430-edit-row" data-ar3980-purchase-row data-index="'+i+'"><div class="ar430-edit-top"><b>ردیف '+fa(i+1)+'</b><input class="input" data-role="title" value="'+esc(r.title)+'" placeholder="شرح خرید"><button type="button" data-ar3980="deletePurchaseRow" data-index="'+i+'">حذف</button></div><div class="ar430-edit-fields"><label>تعداد<input class="input ar430-num" data-role="quantity" inputmode="decimal" value="'+esc(purchaseFaPlain(r.quantity||1))+'"></label><label>واحد<input class="input" data-role="unit" value="'+esc(r.unit||'عدد')+'"></label><label>قیمت واحد<input class="input ar430-num" data-role="unitPrice" inputmode="numeric" value="'+esc(purchaseFaMoneyInput(r.unitPrice))+'"></label><label>تاریخ<input class="input ar430-num" data-role="date" inputmode="numeric" value="'+esc(fa(r.date||''))+'"></label></div><div class="ar430-row-sum">جمع ردیف: <b>'+mon(purchaseNumber(r.quantity)*purchaseNumber(r.unitPrice))+'</b></div></div>'}).join('')+'</div><button class="btn ghost full" data-ar3980="addPurchaseRow">+ افزودن ردیف</button><div class="grid2 ar430-editor-actions"><button class="btn gold" data-ar3980="saveMonthPurchase">ذخیره خریدهای ماه</button><button class="btn ghost" data-action="closeModal">انصراف</button></div></div></div>'}
function purchaseArchiveInMemory(raw){if(!raw)return;if(!Array.isArray(data.recycleBin))data.recycleBin=[];var now=Date.now();data.recycleBin.unshift({id:uidLocal('trash'),type:'purchase',entityId:String(raw.id||''),label:'خرید '+String(raw.title||''),payload:clone(raw),deletedAt:new Date(now).toISOString(),deletedAtMs:now,protectedUntilMs:now+30*86400000})}
function validatePurchaseDraft(d){var valid=(d.rows||[]).filter(function(r){return String(r.title||'').trim()||purchaseNumber(r.unitPrice)||purchaseNumber(r.quantity)>1});if(!valid.length)return {error:'حداقل یک ردیف خرید وارد کن'};for(var i=0;i<valid.length;i++){var r=valid[i],pd=parseDate(r.date);if(!String(r.title||'').trim())return {error:'شرح همه ردیف‌ها را وارد کن'};if(!(purchaseNumber(r.quantity)>0)||!(purchaseNumber(r.unitPrice)>0))return {error:'تعداد و قیمت واحد باید بیشتر از صفر باشند'};if(!pd)return {error:'تاریخ شمسی معتبر وارد کن'};if(n(pd.jy)!==n(d.year)||n(pd.jm)!==n(d.month))return {error:'تاریخ هر ردیف باید مربوط به همین ماه باشد'}}return {rows:valid}}
function saveMonthPurchase(){
  syncPurchaseDraft();var d=state.ar3980PurchaseDraft||{},check=validatePurchaseDraft(d);if(check.error){showToast(check.error);return}
  if(purchaseFingerprint(d.year,d.month)!==String(d.sourceFingerprint||'')){showToast('خریدهای این ماه تغییر کرده‌اند؛ فرم را ببند و دوباره باز کن');return}
  var s=settings(),beforeStore=clone(Array.isArray(s.v37WorkshopPurchases)?s.v37WorkshopPurchases:[])||[],beforeTrash=clone(Array.isArray(data.recycleBin)?data.recycleBin:[])||[],current=beforeStore.slice(),source={};(d.sourceIds||[]).forEach(function(id){source[String(id)]=1});
  try{
    var kept={};check.rows.forEach(function(r){if(r.id)kept[String(r.id)]=1});
    current.forEach(function(raw){if(raw&&source[String(raw.id||'')]&&!kept[String(raw.id||'')])purchaseArchiveInMemory(raw)});
    current=current.filter(function(raw){return !(raw&&source[String(raw.id||'')]&&!kept[String(raw.id||'')])});
    check.rows.forEach(function(r){var q=purchaseNumber(r.quantity),u=purchaseNumber(r.unitPrice),total=Math.round(q*u),id=String(r.id||''),date=fa(purchaseToLatin(r.date));if(id){var at=current.findIndex(function(x){return String(x&&x.id||'')===id});if(at<0)throw new Error('SOURCE_ROW_MISSING');var base=clone(current[at])||{},oldDate=purchaseDate(base),created=base.createdAt;base.title=String(r.title).trim();base.quantity=q;base.unit=String(r.unit||'عدد').trim()||'عدد';base.unitPrice=u;if(Object.prototype.hasOwnProperty.call(base,'unitPriceToman'))base.unitPriceToman=u;base.estimatedAmount=total;base.totalAmount=total;base.purchaseDate=date;if(Object.prototype.hasOwnProperty.call(base,'needDate')&&(!base.needDate||base.needDate===oldDate))base.needDate=date;if(Object.prototype.hasOwnProperty.call(base,'date')&&(!base.date||base.date===oldDate))base.date=date;base.status=base.status||'خرید شد';base.createdAt=created||base.createdAt||new Date().toISOString();base.updatedAt=new Date().toISOString();current[at]=base}else{var now=new Date().toISOString();current.push({id:uidLocal('buy'),title:String(r.title).trim(),quantity:q,unit:String(r.unit||'عدد').trim()||'عدد',unitPrice:u,unitPriceToman:u,estimatedAmount:total,totalAmount:total,purchaseDate:date,needDate:date,status:'خرید شد',createdAt:now,updatedAt:now})}});
    s.v37WorkshopPurchases=current;var ok=saveAll();if(ok===false)throw new Error('SAVE_FAILED');state.modal=null;state.ar3980PurchaseDraft=null;showToast('خریدهای ماه ذخیره شد');renderApp();
  }catch(e){s.v37WorkshopPurchases=beforeStore;data.recycleBin=beforeTrash;console.error('AlanRang workshop purchase save rollback',e);showToast('ذخیره کامل نشد؛ اطلاعات قبلی بدون تغییر حفظ شد')}
}
function normalizePurchaseNumericInput(el){if(!el)return;var old=String(el.value||''),pos=el.selectionStart,out=fa(purchaseToLatin(old)).replace(/\./g,'٫');if(out!==old){el.value=out;try{if(pos!=null)el.setSelectionRange(pos,pos)}catch(_){}}}
