function reportHtml(){var t=today(),y=n(state.ar3980ReportYear)||t.jy,m=n(state.ar3980ReportMonth)||t.jm,current=baseStats(y,m),rows=[],total={sales:0,purchases:0,expenses:0,profit:0};for(var i=1;i<=12;i++){var s=baseStats(y,i);rows.push(s);total.sales+=s.sales;total.purchases+=s.purchases;total.expenses+=s.expenses;total.profit+=s.profit}return '<section class="page ar3980-page"><div class="back-row"><button class="btn ghost" data-action="tab" data-tab="financeHub">برگشت</button></div><div class="ar3980-hero"><h2>گزارش سود واقعی</h2><p>خرید فقط یک‌بار حساب می‌شود؛ پرداخت خرید دوباره از سود کم نمی‌شود.</p></div><div class="ar3980-month-filter"><label>سال<select id="ar3980ReportYear">'+[y-2,y-1,y,y+1].map(function(v){return '<option value="'+v+'" '+(v===y?'selected':'')+'>'+fa(v)+'</option>'}).join('')+'</select></label><label>ماه<select id="ar3980ReportMonth">'+MONTHS.map(function(name,j){return '<option value="'+(j+1)+'" '+(j+1===m?'selected':'')+'>'+name+'</option>'}).join('')+'</select></label></div>'+monthSummaryHtml(y,m)+'<div class="ar3980-table"><table><thead><tr><th>ماه</th><th>کارکرد</th><th>خرید</th><th>هزینه</th><th>سود</th></tr></thead><tbody>'+rows.map(function(r,j){return '<tr><td>'+MONTHS[j]+'</td><td>'+mon(r.sales)+'</td><td>'+mon(r.purchases)+'</td><td>'+mon(r.expenses)+'</td><td>'+mon(r.profit)+'</td></tr>'}).join('')+'</tbody><tfoot><tr><th>جمع سال</th><th>'+mon(total.sales)+'</th><th>'+mon(total.purchases)+'</th><th>'+mon(total.expenses)+'</th><th>'+mon(total.profit)+'</th></tr></tfoot></table></div><div class="ar3980-note">اگر هیچ هزینه دیگری ثبت نکنی، سود ماه همان کارکرد منهای خرید رنگ و وسایل است.</div></section>'}

function searchResults(q){var term=normalize(q);if(!term)return [];var out=[];function add(kind,title,meta,hay,action,id){if(normalize(hay).indexOf(term)>-1)out.push({kind:kind,title:title,meta:meta,action:action,id:id})}(data.customers||[]).forEach(function(c){add('مشتری',c.name||'مشتری',(c.phone||'')+' — '+(c.address||''),[c.name,c.phone,c.address,c.notes,c.balance].join(' '),'account',c.id)});(data.invoices||[]).forEach(function(inv){var c=(data.customers||[]).find(function(x){return x.id===inv.customerId}),sum=(inv.items||[]).reduce(function(s,x){return s+n(x.quantity)*n(x.unitPrice)},0);add('فاکتور','فاکتور '+(inv.invoiceNumber||'—'),(c&&c.name||'')+' — '+mon(sum),[inv.invoiceNumber,inv.date,inv.projectTitle,inv.description,c&&c.name,(inv.items||[]).map(function(x){return x.description}).join(' ')].join(' '),'previewInvoice',inv.id)});finance().forEach(function(x){add((x.type==='چک'||x.method==='چک')?'چک':'مالی',(x.type||'ثبت مالی')+' '+mon(x.amount),(x.date||'')+' — '+(x.status||''),[x.type,x.method,x.amount,x.date,x.dueDate,x.status,x.bankName,x.checkNumber,x.ownerName,x.spentTo,x.notes].join(' '),'ar3980OpenFinance',x.id)});purchaseStore().forEach(function(p){add('خرید',p.title||'خرید',mon(rowAmount(p))+' — '+(p.purchaseDate||p.needDate||''),[p.title,p.supplier,p.invoiceNo,p.note,p.purchaseDate,p.needDate,p.amount,p.estimatedAmount].join(' '),'ar3980OpenPurchase',p.id)});(data.workReservations||[]).forEach(function(r){add('رزرو',r.title||'رزرو',r.date||'',[r.title,r.date,r.workType,r.notes,r.count].join(' '),'editWorkReservation',r.id)});(data.executiveWorks||[]).forEach(function(w){add('کار',w.title||'کار',w.startDate||'',[w.title,w.notes,w.status,w.owner,w.startDate,w.endDate].join(' '),'editExecutionWork',w.id)});return out.slice(0,150)}
function searchHtml(){var q=String(state.ar3980Search||''),rows=searchResults(q);return '<section class="page ar3980-page"><div class="back-row"><button class="btn ghost" data-action="tab" data-tab="'+attr(state.ar3980SearchBack||'home')+'">برگشت</button></div><div class="ar3980-hero"><h2>جست‌وجوی کل برنامه</h2><p>مشتری، فاکتور، چک، مالی، خرید، رزرو و کار را هم‌زمان جست‌وجو می‌کند.</p></div><input id="ar3980SearchInput" class="input ar3980-search-input" value="'+esc(q)+'" placeholder="نام، شماره، مبلغ، شرح یا تاریخ..." autofocus><div class="ar3980-results">'+(!q?'<div class="ar3980-empty">عبارت جست‌وجو را وارد کن.</div>':(rows.map(function(r){return '<button data-action="'+attr(r.action)+'" data-id="'+attr(r.id)+'"><span>'+esc(r.kind)+'</span><div><b>'+esc(r.title)+'</b><small>'+esc(r.meta)+'</small></div></button>'}).join('')||'<div class="ar3980-empty">نتیجه‌ای پیدا نشد.</div>'))+'</div></section>'}

