function trashHtml(){var rows=trash(),eligible=rows.filter(function(x){return n(x.protectedUntilMs)<=Date.now()}).length;return '<section class="page ar3980-page"><div class="back-row"><button class="btn ghost" data-action="tab" data-tab="more">برگشت</button>'+(eligible?'<button class="btn red" data-ar3980="purgeTrash">پاک‌سازی قدیمی‌ها</button>':'')+'</div><div class="ar3980-hero"><h2>حذف‌شده‌ها</h2><p>هر مورد حداقل ۳۰ روز امن می‌ماند و با دکمه بازگردانی به جای قبلی برمی‌گردد.</p></div><div class="ar3980-trash">'+(rows.map(function(x){var left=Math.max(0,30-ageDays(x));return '<article><div><b>'+esc(x.label||'مورد حذف‌شده')+'</b><small>حذف: '+fa(ageDays(x))+' روز قبل — '+(left?'تا '+fa(left)+' روز دیگر محافظت می‌شود':'آماده پاک‌سازی اختیاری')+'</small></div><button data-ar3980="restoreTrash" data-id="'+attr(x.id)+'">بازگردانی</button></article>'}).join('')||'<div class="ar3980-empty">چیزی حذف نشده است.</div>')+'</div></section>'}

