function ensureSearchButton(){var old=document.getElementById('ar383SearchTrigger');if(old)old.remove();if(document.getElementById('ar3980SearchTrigger'))return;var b=document.createElement('button');b.id='ar3980SearchTrigger';b.className='ar3980-search-trigger no-print';b.setAttribute('aria-label','جست‌وجوی کل برنامه');b.innerHTML='<svg viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 5 5"/></svg>';document.body.appendChild(b)}
